update ujcms_schedule_task
set order_ = order_ + 1
where order_ < #{from} and order_ >= #{to}

update ujcms_schedule_task
set order_ = order_ - 1
where order_ > #{from} and order_ <= #{to}

update ujcms_schedule_task
set order_ = #{order}
where id_ = #{id}

update ujcms_schedule_task
set last_run_at_ = #{lastRunAt,jdbcType=TIMESTAMP},
  last_status_ = #{lastStatus,jdbcType=SMALLINT},
  error_info_ = #{errorInfo,jdbcType=LONGVARCHAR}
where id_ = #{id,jdbcType=BIGINT}

